  console.log("DNS", ms(dnsMs), "· connect", ms(connectMs), "· TLS", ms(tlsMs), "· wait", ms(waitMs), "· download", ms(downloadMs));
  console.log(reusedConnection ? "Reused an open connection" : "Opened a new connection");
  ancr.test("no phase is negative", () => {
