items.testScript:
// Connect, send a message: the tests run again as messages arrive.
ancr.test("something comes back", () => {
  ancr.expect(ancr.messages.some((m) => m.direction === "received")).toBe(true);
});
ancr.test("what's sent is echoed", () => {
  const sent = ancr.messages.filter((m) => m.direction === "sent").map((m) => m.data);
  const received = ancr.messages.filter((m) => m.direction === "received").map((m) => m.data);
  ancr.expect(sent.every((text) => received.includes(text))).toBe(true);
});

// Publish {"status":"paid"} to ancr/sample/orders/1 on the Publish tab.
ancr.test("an order is paid within 30 s", () => {
  const paid = ancr.messages.find((m) => m.direction === "received" && m.json().status === "paid");
  ancr.expect(paid).toBeDefined();
  ancr.expect(paid.at).toBeLessThan(30000);
});
